const paymentEscape=value=>String(value||'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const rupiah=value=>new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(value);
const id=new URLSearchParams(location.search).get('order')||localStorage.getItem('ruangrupa-current-order');
let orders=JSON.parse(localStorage.getItem('ruangrupa-orders')||'[]'),order=orders.find(item=>item.id===id);
if(!order){document.querySelector('.page').innerHTML='<section class="card"><h1>Pesanan tidak ditemukan.</h1><a href="index.html">Kembali ke katalog</a></section>';throw new Error('Order not found')}
const instructions={
 'Virtual Account':['Gunakan nomor virtual account berikut:','8808 1234 5678'],
 'QRIS':['Pindai kode QR simulasi berikut:','QR-RUANGRUPA-'+order.id.slice(-4)],
 'E-wallet':['Buka aplikasi e-wallet lalu gunakan kode:','EW-'+order.id.slice(-6)],
 'Transfer Bank':['Transfer simulasi ke rekening berikut:','123 456 7890']
};
Object.assign(instructions,{credit_card:['Pembayaran diproses melalui Midtrans Sandbox:','Kartu pengujian Midtrans'],bank_transfer:['Pembayaran diproses melalui Midtrans Sandbox:','Virtual Account pengujian'],gopay:['Pembayaran diproses melalui Midtrans Sandbox:','GoPay pengujian'],qris:['Pembayaran diproses melalui Midtrans Sandbox:','QRIS pengujian'],cstore:['Pembayaran diproses melalui Midtrans Sandbox:','Gerai pengujian']});
function save(){orders=orders.map(item=>item.id===order.id?order:item);localStorage.setItem('ruangrupa-orders',JSON.stringify(orders))}
function render(){document.querySelector('#orderId').textContent=order.id;document.querySelector('#items').innerHTML=order.items.map(item=>`<div class="item"><span>${paymentEscape(item.name)}${item.colorName?` — ${paymentEscape(item.colorName)}`:''} × ${item.qty}</span><strong>${rupiah(item.price*item.qty)}</strong></div>`).join('');document.querySelector('#subtotal').textContent=rupiah(order.subtotal);document.querySelector('#shipping').textContent=rupiah(order.shipping);document.querySelector('#discount').textContent='− '+rupiah(order.discount);document.querySelector('#total').textContent=rupiah(order.total);document.querySelector('#expiry').textContent='Batas simulasi: '+new Date(order.expiresAt).toLocaleString('id-ID');const labels={paid:'Pembayaran berhasil',failed:'Pembayaran gagal',expired:'Pembayaran kedaluwarsa',cancelled:'Pesanan dibatalkan',refunded:'Dana dikembalikan'},status=document.querySelector('#status'),finished=['paid','failed','expired','cancelled','refunded'].includes(order.status),paidButton=document.querySelector('#paid'),failedButton=document.querySelector('#failed');status.className='pill '+(order.status==='paid'?'paid':order.status==='pending'?'':'failed');status.textContent=labels[order.status]||'Menunggu pembayaran';document.querySelectorAll('.method').forEach(button=>{button.classList.toggle('active',button.dataset.method===order.method);button.disabled=finished});paidButton.disabled=finished;failedButton.disabled=finished;paidButton.textContent=order.status==='paid'?'Pembayaran berhasil':'Simulasikan berhasil';failedButton.textContent=order.status==='failed'?'Pembayaran gagal':'Simulasikan gagal';const copy=instructions[order.method];document.querySelector('#instruction').textContent=copy[0];document.querySelector('#code').textContent=copy[1];document.querySelector('.notice').textContent=finished?'Status pembayaran sudah tersimpan dan disinkronkan ke dashboard admin.':order.paymentToken?'Status simulasi akan disinkronkan ke dashboard admin.':'Pesanan lama: status hanya tersimpan di perangkat ini.';const midtransPay=document.querySelector('#midtransPay');if(midtransPay&&finished){midtransPay.disabled=true;midtransPay.textContent=order.status==='paid'?'Pembayaran Midtrans berhasil':order.status==='expired'?'Pembayaran kedaluwarsa':'Pembayaran sudah selesai'}}
async function syncServerStatus(){if(!order.paymentToken)return;try{const response=await fetch(`/api/midtrans/${encodeURIComponent(order.id)}/status?token=${encodeURIComponent(order.paymentToken)}`,{cache:'no-store'}),data=await response.json();if(!response.ok)return;if(data.orderStatus&&data.orderStatus!==order.status){order.status=data.orderStatus;if(order.status==='paid')order.paidAt=data.payment?.paidAt||new Date().toISOString();save();render()}if(order.status==='pending')setTimeout(syncServerStatus,10000)}catch{if(order.status==='pending')setTimeout(syncServerStatus,15000)}}
async function simulate(status){const paid=document.querySelector('#paid'),failed=document.querySelector('#failed');paid.disabled=true;failed.disabled=true;const active=status==='paid'?paid:failed,original=active.textContent;active.textContent='Menyinkronkan…';try{if(order.paymentToken){const response=await fetch(`/api/payments/${encodeURIComponent(order.id)}/simulate`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({status,method:order.method,token:order.paymentToken})}),data=await response.json();if(!response.ok)throw new Error(data.error||'Status belum dapat disinkronkan');order.status=data.status}else order.status=status;if(status==='paid')order.paidAt=new Date().toISOString();save();render()}catch(error){document.querySelector('.notice').textContent=error.message;paid.disabled=false;failed.disabled=false;active.textContent=original}}
document.querySelectorAll('.method').forEach(button=>button.addEventListener('click',()=>{order.method=button.dataset.method;save();render()}));
document.querySelector('#paid').addEventListener('click',()=>simulate('paid'));
document.querySelector('#failed').addEventListener('click',()=>simulate('failed'));
const invoiceStyle=document.createElement('style');invoiceStyle.textContent='#printInvoice{display:none}@media print{@page{size:A4;margin:15mm}body{background:white!important;color:#111!important;font:12pt/1.5 Arial,sans-serif}body>*{display:none!important}body>#printInvoice{display:block!important}#printInvoice h1{font:700 24pt Arial,sans-serif;margin:0}#printInvoice h2{font:700 15pt Arial,sans-serif}#printInvoice table{width:100%;border-collapse:collapse;margin:20px 0}#printInvoice th,#printInvoice td{padding:8px;border-bottom:1px solid #ccc;text-align:left;overflow-wrap:anywhere}#printInvoice tr{break-inside:avoid}#printInvoice .money{text-align:right}#printInvoice .invoice-totals{margin-left:auto;width:65%;break-inside:avoid}#printInvoice .invoice-note{margin-top:24px;border-top:1px solid #ccc;padding-top:12px}}';document.head.append(invoiceStyle);
const printInvoice=document.createElement('section');printInvoice.id='printInvoice';document.body.append(printInvoice);
function prepareInvoice(){const esc=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char])),customer=order.customer||{},labels={pending:'Menunggu pembayaran',paid:'Pembayaran berhasil',failed:'Pembayaran gagal',expired:'Pembayaran kedaluwarsa',cancelled:'Pesanan dibatalkan',refunded:'Dana dikembalikan'};printInvoice.innerHTML=`<h1>RuangRupa</h1><h2>INVOICE SIMULASI</h2><p><strong>Nomor pesanan:</strong> ${esc(order.id)}<br><strong>Tanggal:</strong> ${esc(order.createdAt?new Date(order.createdAt).toLocaleString('id-ID'):'—')}<br><strong>Status:</strong> ${esc(labels[order.status]||'Menunggu pembayaran')}</p><h2>Pelanggan</h2><p>${esc(customer.name||'—')}<br>${esc(customer.phone||'')}<br>${esc(customer.email||'')}<br>${esc(customer.address||'')}<br>${esc(customer.city||'')} ${esc(customer.postal||'')}</p><table><thead><tr><th>Produk</th><th>Jumlah</th><th class="money">Harga satuan</th><th class="money">Jumlah harga</th></tr></thead><tbody>${order.items.map(item=>`<tr><td>${esc(item.name)}${item.colorName?`<br><small>Warna: ${esc(item.colorName)}</small>`:''} </td><td>${esc(item.qty)}</td><td class="money">${rupiah(item.price)}</td><td class="money">${rupiah(item.price*item.qty)}</td></tr>`).join('')}</tbody></table><div class="invoice-totals"><div class="line"><span>Subtotal</span><strong>${rupiah(order.subtotal)}</strong></div><div class="line"><span>Pengiriman</span><strong>${rupiah(order.shipping)}</strong></div><div class="line"><span>Diskon</span><strong>− ${rupiah(order.discount)}</strong></div><div class="line total"><span>Total</span><strong>${rupiah(order.total)}</strong></div></div><p class="invoice-note">Dokumen percobaan. Tidak ada uang nyata yang ditagihkan atau barang yang dikirim. Invoice ini bukan bukti pembayaran nyata.</p>`}
window.addEventListener('beforeprint',prepareInvoice);
document.querySelector('#invoice').addEventListener('click',()=>{prepareInvoice();window.print()});if(order.paymentToken){const trackingLink=document.createElement('a');trackingLink.className='btn secondary';trackingLink.href=`track.html?order=${encodeURIComponent(order.id)}`;trackingLink.textContent='Lacak pesanan';trackingLink.style.display='block';trackingLink.style.textAlign='center';document.querySelector('#invoice').after(trackingLink)}render();syncServerStatus();const midtransScript=document.createElement('script');midtransScript.src='midtrans.js';document.body.append(midtransScript);
